"""Galeria projektu Forma. Prywatne dane wejściowe zapisuje wyłącznie poza repo."""
from pathlib import Path
from html import escape as E
import argparse,json,re
root=Path(__file__).resolve().parents[2]
base=Path(__file__).with_name('t14-build-mockups.py')
ns={'__file__':str(base)}
exec(compile(base.read_text().split("for v in ['focus','table','cards']:",1)[0],str(base),'exec'),ns)
parser=argparse.ArgumentParser();parser.add_argument('--data');parser.add_argument('--out',default=str(base.parent/'t14-full-gallery.html'));args=parser.parse_args()
if args.data:data=json.loads(Path(args.data).read_text())
else:
 data={'name':'Plan demonstracyjny','filename':'Plan demonstracyjny.pdf','pages':2,'private':False,'sessions':[]}
 for label,items in [('A',ns['A']),('B',ns['B'])]:
  data['sessions'].append({'label':label,'page':1,'exercises':[dict(name=e['name'],original=e['name'],count=e['sets'].split(' × ')[0],reps=e['sets'].split(' × ')[1],rest=e['rest'],intensity=e['intensity'],group=e['group'],code='',advice='Kontroluj ruch zgodnie z zaleceniem w planie.',note='',progression='',page=1,rawSeries=e['sets'].split(' × ')[0],rawReps=e['sets'].split(' × ')[1],kg=e['load']) for e in items]})
out=Path(args.out).resolve()
if data.get('private') and out.is_relative_to(root):raise ValueError('Prywatna makieta musi powstać poza repozytorium')
out.parent.mkdir(parents=True,exist_ok=True)
ico=ns['ico']; exicon=ns['exicon'];css=ns['css']
ns['figs'].update({'handstand':'<path class="equipment" d="M8 56h48M12 55v-7h6"/><circle cx="32" cy="45" r="4"/><path d="M32 37V23m0 10-12 9-3 13m15-22 12 9 3 13M32 23l-9-16m9 16 8-16M19 6h8m9 0h8"/>','dip':'<path class="equipment" d="M9 31h13m20 0h13M14 31v24m36-24v24"/><circle cx="32" cy="12" r="4"/><path d="M32 20v16m0-13-12 8m12-8 12 8M32 36l-9 10 9 9m0-19 9 10-9 9"/>','core':'<path class="equipment" d="M6 55h52"/><circle cx="15" cy="44" r="4"/><path d="m22 46 14-13 5-21m-5 21 13-13M26 42l-1 12H10"/>','band':'<circle cx="30" cy="12" r="4"/><path d="M30 20v20m0-17-10 9 7 8m3-17 10 9-7 8M30 40l-9 15m9-15 9 15"/><path class="equipment" d="M26 40h8"/>'})
def iconfor(name):
 n=name.lower()
 for key,words in [('handstand',['handstand','rękach']),('bench',['bench','leżąc']),('dip',['dip']),('squat',['squat','przysiad','lunge','leg press','abduction']),('press',['press','push up']),('pull',['pull','chin','muscle']),('dead',['deadlift']),('plank',['plank','deska']),('core',['flag','sit-up','wiper','thrust']),('band',['rotation','curl','extension'])]:
  if any(w in n for w in words):return key
 return 'row'
def name(ex):
 aliases={'handstand* nauka':'Stanie na rękach','muscle up z gumą':'Muscle-up z gumą','front squat':'Przysiad przedni','bench press':'Wyciskanie leżąc','pull up':'Podciąganie','bar dip':'Dipy na poręczach','romanian deadlift':'Martwy ciąg rumuński','pike push up':'Pike push-up','ring biceps curl':'Uginanie na kółkach','ring triceps extension':'Prostowanie na kółkach'}
 return aliases.get(ex['name'],ex['name'])
def normal(s):return re.sub(r'\s*-\s*','–',str(s)).strip()
def rest(ex):
 s=normal(ex['rest'])
 if not s or re.fullmatch('[—–-]+',s):return 'Nie podano'
 if re.search(r'\d',s) and not re.search(r'(min|sek|s$)',s):s+=' s'
 return s

def goal(ex):
 c=ex['rawSeries'].splitlines();r=ex['rawReps'].splitlines()
 if len(c)==2 and re.fullmatch(r'\d+',c[0]) and re.fullmatch(r'\d+-\d+',c[1]):return normal(c[0])+' × '+normal(r[0])+' + '+normal(c[1])+' × '+normal(r[1])
 return normal(ex['count'])+' × '+normal(ex['reps'])
def button(text,go=None,secondary=False,extra=''):
 return '<button class="btn '+('secondary' if secondary else '')+'" '+(f'data-go="{go}"' if go else '')+' '+extra+'>'+text+'</button>'
def sessiontabs(si):
 return '<div class="tabs" role="group" aria-label="Trening">'+''.join(f'<button data-session="{i}" class="{"on" if si==i else ""}">{E(s["label"])}</button>' for i,s in enumerate(data['sessions']))+'</div>'
def row(title,subtitle='',go='plan',symbol='plans',extra=''):
 return f'<button class="settingrow" data-go="{go}" {extra}><span class="rowicon">{ico(symbol)}</span><span><strong>{E(title)}</strong><small>{E(subtitle)}</small></span>{ico("chevron","chev")}</button>'
def demo():return '<p class="demo-note">Wyniki demonstracyjne · to nie historia Twojego konta</p>'
def plan_list(si=0):
 return ''.join(f'<button class="dayrow" data-session="{i}" data-go="plan"><span class="dayletter">{E(s["label"])}</span><span class="daycopy"><strong>Trening {E(s["label"])}</strong><small>{len(s["exercises"])} ćwiczeń · z dokumentu</small></span>{ico("chevron","chev")}</button>' for i,s in enumerate(data['sessions']))
def summary(ex,ei,editable=False):
 load=ex.get('kg') or ex['intensity'];loadlabel='Obciążenie' if ex.get('kg') else 'Intens. źródłowa'
 label=('Superseria '+ex['code'].split()[0].replace('ss','')) if ex['code'].startswith('ss') else ('Zakres serii' if '–' in normal(ex['count']) else 'Zalecenie z planu')
 return f'<article class="exercise"><button class="exercise-top" data-go="detail" data-ex="{ei}"><span class="thumb">{exicon(iconfor(ex["name"]))}</span><span class="ename"><strong>{E(name(ex))}</strong><small>{E(label)}</small></span>{ico("chevron","chev")}</button><div class="metrics"><div><small>Serie × cel</small><strong>{E(goal(ex))}</strong></div><div><small>{loadlabel}</small><strong>{E(load)}</strong></div><div><small>Przerwa</small><strong>{E(rest(ex))}</strong></div></div>'+('<button class="textbtn edit-series" data-inline>Edytuj serie</button><div class="inline-edit" hidden><label>Serie<input value="'+E(ex['count'])+'"></label><label>Cel<input value="'+E(ex['reps'])+'"></label><button class="btn secondary" data-local>Zastosuj w makiecie</button></div>' if editable else '')+'</article>'
def source(ex):
 image=(f'<img src="source-{ex["page"]}.png" alt="Strona {ex["page"]} źródłowego dokumentu" loading="lazy">' if data.get('private') else '<div class="note">Źródło demonstracyjne. W prywatnej galerii dostępny jest widok strony PDF.</div>')
 return f'<details class="source"><summary>Oryginał i źródło · strona {ex["page"]}</summary><p>{E(ex["original"])} · serie {E(ex["count"])} · cel {E(ex["reps"])} · przerwa {E(ex["rest"])} · intensywność {E(ex["intensity"])}</p>{image}</details>'
def series(ex):
 rawc=ex['rawSeries'].splitlines();rawr=ex['rawReps'].splitlines(); rows=[]
 if len(rawc)==2 and re.fullmatch(r'\d+',rawc[0]) and re.fullmatch(r'\d+-\d+',rawc[1]):
  rows=[(i+1,rawr[0],'') for i in range(int(rawc[0]))];rng=rawc[1].split('-');rows +=[(len(rows)+i+1,rawr[1],'zakres' if i>=int(rng[0]) else '') for i in range(int(rng[-1]))]
 else:
  nums=re.findall(r'\d+',ex['count']);count=min(int(nums[-1]),10) if nums else 1
  rows=[(i+1,normal(ex['reps']),'zakres' if len(nums)>1 and i>=int(nums[0]) else '') for i in range(count)]
 return '<table class="series"><caption>Serie w źródle</caption><thead><tr><th>Seria</th><th>Cel</th><th>Intens.</th><th>Przerwa</th></tr></thead><tbody>'+''.join(f'<tr><td>{n}{" · "+tag if tag else ""}</td><td>{E(str(r))}</td><td>{E(ex["intensity"])}</td><td>{E(rest(ex))}</td></tr>' for n,r,tag in rows)+'</tbody></table>'
def selected(screen,si,ei):
 session=data['sessions'][si];ex=session['exercises'][ei]
 if screen=='plans':
  return '<div class="headline"><div><h1>Twoje plany</h1><p class="sub">Prywatna makieta · źródło PDF</p></div></div><div class="private-track" tabindex="0" role="region" aria-label="Wybór planu"><section class="planblock"><h2>'+E(data['name'])+'</h2><p>'+str(len(data['sessions']))+' treningi · '+str(sum(len(s['exercises']) for s in data['sessions']))+' ćwiczeń</p>'+button('Otwórz plan '+ico('chevron'),'plan')+'</section><section class="planblock sampleplan"><h2>Plan demonstracyjny</h2><p>Przykład drugiej karty do sprawdzenia gestu</p>'+button('Wróć do Twojego planu',None,extra='data-carousel-back')+'</section></div><div class="carousel-controls"><button class="iconbtn" data-carousel-back aria-label="Poprzedni plan">'+ico('back')+'</button><span id="carousel-position">Plan 1 z 2</span><button class="iconbtn" data-carousel-next aria-label="Następny plan">'+ico('chevron')+'</button></div><h2 class="sectiontitle">Treningi w Twoim planie</h2>'+plan_list()+ '<div class="split-actions">'+button('Importuj plan','import',True)+button('Utwórz ręcznie','editor',True)+'</div>'
 if screen=='plan':
  return '<div class="headline compact"><h1>'+E(data['name'])+'</h1><button class="iconbtn" data-go="editor" aria-label="Edytuj plan">'+ico('edit')+'</button></div>'+sessiontabs(si)+f'<div class="sectionhead"><h2>Trening {E(session["label"])}</h2><span>{len(session["exercises"])} ćwiczeń</span></div><p class="source-note">% to intensywność ze źródła · kg nie podano</p>'+''.join(summary(e,i) for i,e in enumerate(session['exercises']))
 if screen=='detail':
  return '<div class="detailtitle"><span class="thumb">'+exicon(iconfor(ex['name']))+'</span><div><h1>'+E(name(ex))+'</h1><p class="sub">Trening '+E(session['label'])+' · strona '+str(ex['page'])+'</p></div></div><div class="facts"><div><strong>'+E(goal(ex))+'</strong><small>Serie × cel</small></div><div><strong>'+E(ex['intensity'])+'</strong><small>Intensywność źródłowa</small></div><div><strong>'+E(rest(ex))+'</strong><small>Przerwa</small></div></div><p class="source-note">Brak podanych kg. Nie zakładamy, że procent dotyczy 1RM.</p>'+series(ex)+''.join(f'<div class="note distinct"><strong>{label}</strong>{E(ex[key])}</div>' for label,key in [('Wskazówka w planie','advice'),('Uwagi indywidualne','note'),('Kierunek progresji w źródle','progression')] if ex[key])+source(ex)
 if screen=='workout':
  target=normal(ex['reps']);timed=bool(re.search(r'(sek| s)',target));isnumber=bool(re.fullmatch(r'\d+',target));amount=target if isnumber else ''
  return '<div class="detailtitle"><span class="thumb">'+exicon(iconfor(ex['name']))+'</span><div><h1>'+E(name(ex))+'</h1><p class="sub">Trening '+E(session['label'])+' · seria 1</p></div></div><div class="goal"><small>Cel w źródle</small><strong>'+E(target)+('' if timed else ' powt.')+'</strong><p class="sub">Intensywność '+E(ex['intensity'])+' · przerwa '+E(rest(ex))+'</p></div><p class="previous">Poprzedni wynik nie jest częścią PDF.<br>Kilogramów nie podano w planie.</p><form id="result"><h2>Twój wynik</h2><div class="fields"><label>'+('Czas (s)' if timed else 'Powtórzenia')+'<input name="reps" inputmode="numeric" placeholder="Wpisz wynik"></label><label>Obciążenie (kg)<input name="kg" inputmode="decimal" placeholder="Nie podano"></label></div><p class="helper">Brak obciążenia pozostaje brakiem danych, nie zerem.</p>'+button('Uzupełnij podany cel',None,True,extra=f'type="button" data-fill="{E(amount)}"')+'<div class="minoractions"><button type="button" class="textbtn" data-info="Głos tworzy propozycję do zatwierdzenia. W makiecie nie nagrywamy.">'+ico('mic')+' Dyktuj</button><button type="button" class="textbtn" data-info="Pominięcie jest osobnym stanem, bez fikcyjnego wykonania.">Pomiń serię</button></div>'+button('Zapisz serię '+ico('check'),None,extra='type="submit"')+'<p class="save-status" id="result-status" role="status"></p></form>'+source(ex)

def new_screen(screen,v,si,phase=0):
 session=data['sessions'][si];ex=session['exercises'][0];count=len(session['exercises']);allcount=sum(len(s['exercises']) for s in data['sessions'])
 if screen=='home':
  h='<h1>Twój trening</h1><p class="sub">Wybierz jednostkę z planu.</p>'
  if v=='a':return h+'<section class="planblock homeplan"><h2>'+E(data['name'])+'</h2><p>'+str(len(data['sessions']))+' treningi do wyboru</p>'+button('Otwórz plan','plan',extra='class="btn light"')+'</section><h2 class="sectiontitle">Wybierz trening</h2>'+plan_list()+row('Importuj kolejny plan','Plik, zdjęcie, tekst lub dyktowanie','import','upload')
  if v=='b':return h+'<p class="sectiontitle muted">'+E(data['name'])+'</p>'+plan_list()+ '<div class="split-actions">'+button('Wszystkie plany','plans',True)+button('Importuj','import',True)+'</div><details class="source"><summary>Co zawiera plan?</summary><p>'+str(allcount)+' ćwiczeń w '+str(len(data['sessions']))+' jednostkach. Cele i szczegóły zachowują zapis źródła.</p></details>'
  return h+'<div class="feature-training"><span class="dayletter">'+E(session['label'])+'</span><h2>Trening '+E(session['label'])+'</h2><p>'+str(count)+' ćwiczeń · podgląd zaleceń z pliku</p>'+button('Przejrzyj trening','plan')+'</div><h2 class="sectiontitle">Pierwsze ćwiczenia</h2>'+''.join(row(name(e),goal(e),'detail','workout',f'data-ex="{i}"') for i,e in enumerate(session['exercises'][:3]))+row('Zmień plan','Otwórz bibliotekę planów','plans','plans')
 if screen=='import':
  h='<h1>Import planu</h1><p class="sub">Wybierz źródło. Odczyt jest propozycją do sprawdzenia.</p>'
  file='<div class="file-summary">'+ico('plans')+'<div><strong>'+E(data['filename'])+'</strong><small>'+str(data['pages'])+' stron · PDF · lokalna makieta</small></div></div>'
  actions=[('Plik PDF lub XLSX','Zapisany dokument','upload'),('Zdjęcie lub aparat','Plan z kartki','plans'),('Wklej tekst','Skopiowany plan','edit'),('Dyktuj plan','Propozycja po nagraniu','mic')]
  if v=='a':return h+'<div class="import-list">'+''.join(row(t,d,'review',ic) for t,d,ic in actions)+'</div>'+file+button('Przejrzyj wskazany PDF','review')+'<p class="helper">Makieta korzysta z odczytanego pliku. Nie uruchamia importu AI.</p>'+row('Utwórz plan ręcznie','Dostępne również bez AI','editor','edit')
  if v=='b':return h+'<div class="tabs"><button class="on" data-local>Plik</button><button data-info="W aplikacji dostępny będzie wybór zdjęcia lub aparatu.">Zdjęcie</button><button data-info="Wklejenie tekstu pozostaje dostępną ścieżką importu.">Tekst</button></div><div class="dropzone">'+ico('upload')+'<h2>Dodaj dokument</h2><p>PDF lub XLSX</p><label class="btn secondary">Wybierz plik<input type="file" accept=".pdf,.xlsx" hidden></label></div>'+file+button('Otwórz propozycję z PDF','review')+'<details class="source"><summary>Głos i ręczne wprowadzanie</summary>'+row('Dyktuj plan','Zatwierdź rozpoznaną propozycję','review','mic')+row('Wpisz ręcznie','Bez wywołania AI','editor','edit')+'</details>'
  return h+'<div class="source-grid">'+''.join(f'<button data-go="review">{ico(ic)}<strong>{E(t)}</strong><small>{E(d)}</small></button>' for t,d,ic in actions)+'</div><h2 class="sectiontitle">Twój dokument</h2>'+file+button('Sprawdź odczyt planu','review')+'<div class="note distinct"><strong>Ty zatwierdzasz</strong>Najpierw ćwiczenia, potem serie i superserie, na końcu cały plan.</div>'+button('Utwórz ręcznie','editor',True)
 if screen=='review':
  steps='<div class="review-steps">'+''.join(f'<button data-phase="{i}" class="{"on" if phase==i else ""}">{i+1}. {t}</button>' for i,t in enumerate(['Ćwiczenia','Serie','Podsum.']))+'</div>'
  h='<h1>Sprawdź import</h1><p class="sub">'+E(data['name'])+'</p>'+steps
  issue='<div class="issue"><strong>Do wyjaśnienia</strong><p>Czy „intensywność %” oznacza procent 1RM? Co oznaczają X i UM? Makieta zachowuje zapisy źródłowe.</p><button class="textbtn" data-inline>Wyjaśnij zapis</button><div class="inline-edit" hidden><label>Twoja interpretacja<select><option>Nie rozstrzygnięto</option>Potwierdzony procent 1RM</option>Intensywność opisowa</option>Inne znaczenie</option></select></label><button class="btn secondary" data-local>Zapisz odpowiedź w makiecie</button></div></div>'
  if phase==2:return h+'<div class="note distinct"><strong>Przed zatwierdzeniem</strong>'+str(len(data['sessions']))+' treningi · '+str(allcount)+' ćwiczeń. Niejasności wymagają świadomego rozstrzygnięcia.</div>'+''.join(row('Trening '+s['label'],str(len(s['exercises']))+' ćwiczeń','plan','workout',f'data-session="{i}"') for i,s in enumerate(data['sessions']))+issue+button('Zapisz korektę',None,True,extra='data-info="Symulacja: zapisano korektę lokalnego podglądu. Bez API."')+button('Zatwierdź i utwórz plan',None,extra='disabled aria-describedby="publish-note"')+'<p class="helper" id="publish-note">Zatwierdzenie czeka na rozwiązanie niejasności. To makieta.</p>'
  if v=='a':return h+sessiontabs(si)+('<p class="source-note">Sprawdź nazwy i kolejność. Serie są w następnym kroku.</p>' if phase==0 else issue)+''.join(summary(e,i) for i,e in enumerate(session['exercises'][:4]))+source(ex)+button('Dalej: '+('serie i superserie' if phase==0 else 'podsumowanie'),None,extra=f'data-phase="{phase+1}"')
  if v=='b':return h+issue+'<div class="sectionhead"><h2>Aktualny fragment</h2><span>Trening '+E(session['label'])+'</span></div>'+summary(ex,0)+source(ex)+'<details class="source"><summary>Pozostałe ćwiczenia ('+str(count-1)+')</summary>'+''.join(row(name(e),goal(e),'detail','workout',f'data-ex="{i}"') for i,e in enumerate(session['exercises'][1:],1))+'</details>'+button('Dalej: '+('serie i superserie' if phase==0 else 'podsumowanie'),None,extra=f'data-phase="{phase+1}"')
  src=(f'<img class="source-preview" src="source-{session["page"]}.png" alt="Oryginał planu, strona {session["page"]}">' if data.get('private') else '<div class="source-placeholder"><h2>Dokument źródłowy</h2><p>'+E(name(ex))+' · '+E(goal(ex))+'</p></div>')
  return h+'<div class="tabs"><button data-show-source class="on">Oryginał</button><button data-show-draft>Propozycja</button></div><section id="source-pane">'+src+'</section><section id="draft-pane" hidden>'+sessiontabs(si)+''.join(summary(e,i) for i,e in enumerate(session['exercises'][:3]))+'</section>'+issue+button('Dalej',None,extra=f'data-phase="{phase+1}"')
 if screen=='editor':
  h='<h1>Edytuj plan</h1><p class="sub">Nowa wersja · szkic zmian</p>'
  naming='<label class="field">Nazwa planu<input value="'+E(data['name'])+'"></label>'
  save='<div class="note distinct"><strong>Niezapisany szkic</strong>Publikacja tworzy nową wersję. Historia treningów zachowuje poprzednie cele.</div>'+button('Opublikuj nową wersję',None,extra='data-info="Symulacja publikacji. W aplikacji najpierw walidacja i zatwierdzenie całego planu."')
  if v=='a':return h+naming+sessiontabs(si)+''.join(summary(e,i,True) for i,e in enumerate(session['exercises'][:4]))+save
  if v=='b':return h+naming+sessiontabs(si)+'<h2 class="sectiontitle">'+E(name(ex))+'</h2>'+series(ex)+'<div class="inline-edit"><label>Serie<input value="'+E(ex['count'])+'"></label><label>Powtórzenia / cel<input value="'+E(ex['reps'])+'"></label><label>Przerwa<input value="'+E(ex['rest'])+'"></label></div><details class="source"><summary>Więcej parametrów i uwagi</summary><p>Rodzaj serii, tempo, RPE/RIR, opcjonalność i notatka.</p></details>'+save
  return h+'<h2 class="sectiontitle">Treningi w planie</h2>'+''.join(f'<details class="editor-tree" {"open" if i==si else ""}><summary>{E(s["label"])} · {len(s["exercises"])} ćwiczeń</summary>'+''.join(summary(e,j,True) for j,e in enumerate(s['exercises'][:2]))+'</details>' for i,s in enumerate(data['sessions']))+button('Dodaj ćwiczenie',None,True,extra='data-info="Nowe ćwiczenie dodaje się do świadomie wybranego treningu."')+save
 if screen=='history':
  h='<h1>Historia</h1>'+demo();entry=lambda day,label:row(day+' · Trening '+label,'Przykład: zakończony · otwórz szczegóły','workout','history')
  if v=='a':return h+calendar()+ '<h2 class="sectiontitle">Wybrany dzień · 14.10</h2>'+entry('14 października',data['sessions'][0]['label'])+button('Otwórz trening','workout')+row('Zobacz postęp','Historia ćwiczeń i wyniki','progress','progress')
  if v=='b':return h+'<div class="tabs"><button class="on" data-local>Wszystkie</button><button data-info="Filtr trwających sesji w tej makiecie jest demonstracyjny.">Do wznowienia</button></div><h2 class="sectiontitle">Ten tydzień</h2>'+entry('14 października',data['sessions'][0]['label'])+entry('12 października',data['sessions'][-1]['label'])+'<h2 class="sectiontitle">Poprzedni tydzień</h2>'+entry('7 października',data['sessions'][0]['label'])+'<details class="source"><summary>Filtry daty i planu</summary><label class="field">Od daty<input type="date" value="2026-10-01"></label></details>'+row('Postęp ćwiczenia','Przejdź do wyników','progress','progress')
  return h+'<h2 class="sectiontitle">Październik 2026</h2><div class="date-strip">'+''.join(f'<button data-date="{i}" class="{"on" if i==14 else ""}"><small>{d}</small><strong>{i}</strong></button>' for i,d in [(12,'pn'),(13,'wt'),(14,'śr'),(15,'cz'),(16,'pt'),(17,'sb'),(18,'nd')])+'</div><section class="feature-training"><p>Wybrano 14 października</p><h2>Trening '+E(data['sessions'][0]['label'])+'</h2><p>Zakończony · przykład widoku dnia</p>'+button('Otwórz zapis','workout')+'</section>'+calendar(compact=True)
 if screen=='progress':
  h='<h1>Postęp</h1>'+demo();select='<label class="field">Ćwiczenie i wariant<select><option>Wyciskanie leżąc · przykład</option><option>Podciąganie · przykład</option></select></label>'
  table='<table class="series"><caption>Wpisane wyniki · przykład</caption><thead><tr><th>Data</th><th>Powt.</th><th>kg</th></tr></thead><tbody><tr><td>14.10</td><td>5</td><td>62,5</td></tr><tr><td>7.10</td><td>5</td><td>60</td></tr></tbody></table>'
  if v=='a':return h+select+'<section class="result-highlight"><small>Ostatni demonstracyjny wynik</small><h2>5 powt. × 62,5 kg</h2><p>14 października · ten sam wariant</p></section>'+table+'<div class="note"><strong>Porównywalne dane</strong>Masa ciała, asysta i brakujące obciążenie nie są sumowane jak kg zewnętrzne.</div>'+button('Otwórz trening','workout',True)
  if v=='b':return h+select+chart()+table
  return h+'<div class="tabs"><button class="on" data-local>Ćwiczenie</button><button data-info="Wykonanie porównuje serie wymagane, opcjonalne i pominięte osobno.">Wykonanie planu</button></div>'+select+'<h2 class="sectiontitle">Dwa ostatnie wpisy</h2><div class="comparison"><section><small>7 października</small><strong>5 × 60 kg</strong><span>Wpisany wynik</span></section><section><small>14 października</small><strong>5 × 62,5 kg</strong><span>Wpisany wynik</span></section></div><div class="note distinct"><strong>Wynik nie jest 1RM</strong>Widok porównuje wykonane serie. Nie wylicza ani nie podmienia rzeczywistych maksimów.</div>'+table
