  if v=='a':return h+'<div class="profile-ident">'+ico('profile')+'<div><h2>Twoje konto</h2><p>Prywatne plany i wykonanie</p></div></div>'+form+'<h2 class="sectiontitle">Ustawienia</h2>'+settings+'<p class="helper">Historia 1RM zachowuje daty. Zmiana nie przelicza starych treningów.</p>'
