script='''<script>
function tell(d){parent.postMessage({fullMock:true,...d},'*')}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.dataset.go)tell({go:b.dataset.go,session:b.dataset.session,ex:b.dataset.ex});else if(b.dataset.session!==undefined)tell({session:b.dataset.session});else if(b.dataset.phase!==undefined)tell({phase:Number(b.dataset.phase),confirmPhase:b.dataset.confirm!==undefined?Number(b.dataset.confirm):undefined});else if(b.hasAttribute('data-inline')){const t=b.nextElementSibling;t.hidden=!t.hidden;b.setAttribute('aria-expanded',!t.hidden)}else if(b.hasAttribute('data-local')){let m=document.getElementById('local-status');if(!m){m=document.createElement('p');m.id='local-status';m.setAttribute('role','status');m.className='source-note';b.after(m)}m.textContent='Zmieniono tylko lokalną makietę.'}else if(b.hasAttribute('data-fill')){if(b.dataset.fill){document.querySelector('[name=reps]').value=b.dataset.fill}else tell({info:'Ten cel wymaga interpretacji źródła. Wpisz wykonany wynik ręcznie.'})}else if(b.dataset.info)tell({info:b.dataset.info});else if(b.hasAttribute('data-show-source')||b.hasAttribute('data-show-draft')){document.getElementById('source-pane').hidden=b.hasAttribute('data-show-draft');document.getElementById('draft-pane').hidden=b.hasAttribute('data-show-source')}else if(b.hasAttribute('data-toggle-settings')){document.getElementById('profile-settings').hidden=false;document.getElementById('profile-max').hidden=true}else if(b.dataset.date){document.querySelectorAll('[data-date]').forEach(x=>x.classList.toggle('on',x===b));tell({info:'Wybrano '+b.dataset.date+' października. Zawartość historii jest demonstracyjna.'})}else if(b.hasAttribute('data-carousel-next')||b.hasAttribute('data-carousel-back')){let t=document.querySelector('.private-track');t.scrollTo({left:b.hasAttribute('data-carousel-next')?t.scrollWidth:0,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'})}});
const track=document.querySelector('.private-track');if(track){track.addEventListener('scroll',()=>{document.getElementById('carousel-position').textContent='Plan '+(track.scrollLeft>track.clientWidth/2?2:1)+' z 2'});track.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();track.scrollTo({left:e.key==='ArrowRight'?track.scrollWidth:0,behavior:'smooth'})}})}
const f=document.getElementById('result');if(f)f.addEventListener('submit',e=>{e.preventDefault();let r=f.elements.reps.value.trim(),k=f.elements.kg.value.trim();document.getElementById('result-status').textContent=!r?'Wpisz wykonany wynik.':'Symulacja: '+r+' · '+(k?k+' kg':'bez wpisanych kg')+'. Bez zapisu do aplikacji.'});const login=document.getElementById('login-form');if(login)login.addEventListener('submit',e=>{e.preventDefault();document.getElementById('login-status').textContent='Makieta: nie wysłano danych logowania.'});
</script>'''
def render_frame(screen,v='a',si=0,ei=0,phase=0):
 variant='cards' if screen=='workout' else 'focus'
 body=selected(screen,si,ei) if screen in all_types[:4] else new_screen(screen,v,si,phase)
 back=screen in ['detail','workout','review','editor'];header=ns['header'](back,label='Wróć do planu')
 foot='<div class="footer-action">'+button('Rozpocznij trening '+E(data['sessions'][si]['label']),'workout')+'</div>' if screen=='plan' else ''
 active={'home':'Trening','workout':'Trening','history':'Historia','progress':'Postęp','profile':'Profil'}.get(screen,'Plany')
 nav=ns['nav'](active)
 nav=nav.replace('data-go="workout"','data-go="home"').replace('data-go="plans"','data-go="plans"').replace('data-go="history"','data-go="history"')
 return '<!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>'+css+extra+'</style></head><body><div class="screen '+variant+'">'+header+'<main class="scroll"><div class="body">'+body+'</div></main>'+foot+(nav if screen!='login' else '')+'</div>'+script+'</body></html>'
