exec(compile((base.parent/'t14-r3-ui.py').read_text(),str(base.parent/'t14-r3-ui.py'),'exec'),globals())
exec(compile((base.parent/'t14-r4-ui.py').read_text(),str(base.parent/'t14-r4-ui.py'),'exec'),globals())
frames={}
for s in all_types:
 for si in range(len(data['sessions'])) if s in ['plan','detail','workout','review','editor','home'] else [0]:
  for ei in range(len(data['sessions'][si]['exercises'])) if s in ['detail','workout'] else [0]:
   for phase in range(3) if s=='review' else [0]:
    for v in ['a'] if s in all_types[:4] else ['a','b','c']:
     frames[f'{s}:{v}:{si}:{ei}:{phase}']=render_frame(s,v,si,ei,phase)
